const data = $input.item.json.body;

function slugify(str) {
  return String(str)
    .toLowerCase()
    .trim()
    .replace(/[^\w\u0600-\u06FF\s-]/g, '')
    .replace(/\s+/g, '-')
    .slice(0, 60);
}

const slugSource = data.company_name_en || data.company_name_ar || 'unknown-client';
const slug = slugify(slugSource);

const record = {
  received_at: new Date().toISOString(),
  slug,
  form_data: data
};

return [{ json: { slug, record } }];

// stdout from claude -p --output-format json is a JSON string in $json.stdout
let result;
try {
  result = JSON.parse($input.item.json.stdout);
} catch (e) {
  result = { subtype: 'parse_error', raw: $input.item.json.stdout };
}
return [{ json: result }];
